input.schema:
{
  "type": "record",
  "name": "Appointment",
  "namespace": "axt.example.v1",
  "doc": "An appointment: an event at a time and possibly a place, such as a visit to the vet.",
  "axt.version": 1,
  "axt.title": "title",
  "axt.label": "Appointment",
  "axt.label_translations": {
    "de": "Termin"
  },
  "axt.help": "An event at a time and possibly a place, such as a visit to the vet.",
  "axt.help_translations": {
    "de": "Ein Ereignis zu einer Zeit und vielleicht an einem Ort, etwa ein Besuch beim Tierarzt."
  },
  "axt.emoji": "📆",
  "fields": [
    {
      "name": "title",
      "type": "string",
      "default": "",
      "doc": "What the appointment is, as plain text on one line.",
      "axt.label": "Title",
      "axt.label_translations": {
        "de": "Titel"
      },
      "axt.help": "What the appointment is, on one line.",
      "axt.help_translations": {
        "de": "Worum es beim Termin geht, in einer Zeile."
      },
      "axt.emoji": "🏷️"
    },
    {
      "name": "start",
      "type": {
        "type": "record",
        "name": "DateTime",
        "namespace": "axt",
        "doc": "A date and time on the wall clock, to the millisecond, either in a time zone of the IANA time zone database, with the offset from UTC and the instant as the writer's zone rules gave them, or floating, on the wall clock of wherever the user is, without zone, offset and instant. Defined in spec/time.md. Its schema never changes.",
        "fields": [
          {
            "name": "year",
            "type": "int",
            "doc": "The year of the proleptic Gregorian calendar, 1 to 9999."
          },
          {
            "name": "month",
            "type": "int",
            "doc": "The month, 1 (January) to 12 (December)."
          },
          {
            "name": "day",
            "type": "int",
            "doc": "The day of the month, 1 to the number of days of that month in that year."
          },
          {
            "name": "hour",
            "type": "int",
            "doc": "The hour on the wall clock, 0 to 23."
          },
          {
            "name": "minute",
            "type": "int",
            "doc": "The minute, 0 to 59."
          },
          {
            "name": "second",
            "type": "int",
            "doc": "The second, 0 to 59; a leap second is not written as 60."
          },
          {
            "name": "millisecond",
            "type": "int",
            "doc": "The millisecond, 0 to 999."
          },
          {
            "name": "zone",
            "type": [
              "null",
              "string"
            ],
            "default": null,
            "doc": "The name of the time zone in the IANA time zone database, such as Europe/Berlin. Null for a floating time; then offset_seconds and instant_ms are null as well."
          },
          {
            "name": "offset_seconds",
            "type": [
              "null",
              "int"
            ],
            "default": null,
            "doc": "The offset of the wall clock from UTC, in seconds, -64800 to 64800, as the writer's rules of the zone gave it at the instant, such as 3600 for 01:00 east of UTC. Null for a floating time, and only then."
          },
          {
            "name": "instant_ms",
            "type": [
              "null",
              "long"
            ],
            "default": null,
            "doc": "The instant, in milliseconds since 1970-01-01T00:00:00Z without leap seconds: the wall clock read as if it were UTC, minus offset_seconds. Null for a floating time, and only then."
          }
        ]
      },
      "doc": "When the appointment starts, as a date and time on the wall clock, in a time zone or floating. For an all-day appointment, 00:00 of its first day, floating.",
      "axt.label": "Start",
      "axt.label_translations": {
        "de": "Beginn"
      },
      "axt.help": "When the appointment starts.",
      "axt.help_translations": {
        "de": "Wann der Termin beginnt."
      },
      "axt.emoji": "🕘",
      "axt.anchor": "local"
    },
    {
      "name": "end",
      "type": [
        "null",
        "axt.DateTime"
      ],
      "default": null,
      "doc": "When the appointment ends: the first moment after it, which is not part of it. It is in a time zone when start is, possibly another one, as for a flight, and floating when start is floating. For an all-day appointment, 00:00 of the day after its last day, floating. Null when no end is given; an all-day appointment without an end takes one day.",
      "axt.label": "End",
      "axt.label_translations": {
        "de": "Ende"
      },
      "axt.help": "When the appointment is over.",
      "axt.help_translations": {
        "de": "Wann der Termin vorbei ist."
      },
      "axt.emoji": "🔚",
      "axt.anchor": "local"
    },
    {
      "name": "all_day",
      "type": "boolean",
      "default": false,
      "doc": "True when the appointment takes whole days; start and end are then floating at 00:00, and only their days count.",
      "axt.label": "All day",
      "axt.label_translations": {
        "de": "Ganztägig"
      },
      "axt.help": "On when the appointment takes whole days.",
      "axt.help_translations": {
        "de": "An, wenn der Termin ganze Tage dauert."
      },
      "axt.emoji": "☀️"
    },
    {
      "name": "location",
      "type": "string",
      "default": "",
      "doc": "Where the appointment takes place, as text, such as an address or a room. Empty when not given.",
      "axt.label": "Location",
      "axt.label_translations": {
        "de": "Ort"
      },
      "axt.help": "Where the appointment takes place, such as an address or a room.",
      "axt.help_translations": {
        "de": "Wo der Termin stattfindet, etwa eine Anschrift oder ein Raum."
      },
      "axt.emoji": "📍"
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the appointment, as plain text; lines are separated by LF. Empty when there are none.",
      "axt.label": "Notes",
      "axt.label_translations": {
        "de": "Notizen"
      },
      "axt.help": "Anything else about the appointment.",
      "axt.help_translations": {
        "de": "Alles Weitere zum Termin."
      },
      "axt.emoji": "📝",
      "axt.multiline": true
    },
    {
      "name": "reminders",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "Duration",
          "namespace": "axt",
          "doc": "A length of time in three parts that are not converted into each other: calendar months, calendar days and elapsed milliseconds, as an INTERVAL of SQL. P1M2DT3H is 1 month, 2 days and 10800000 milliseconds; -PT15M is -900000 milliseconds. The parts that are not 0 all have the same sign. Added to a date and time, the months come first, then the days, then the milliseconds. Defined in spec/time.md. Its schema never changes.",
          "fields": [
            {
              "name": "months",
              "type": "int",
              "doc": "The number of calendar months, negative for a length back in time. A year is 12 months."
            },
            {
              "name": "days",
              "type": "int",
              "doc": "The number of calendar days, negative for a length back in time. A day on the wall clock, which may last 23 or 25 hours where the offset changes; a week is 7 days."
            },
            {
              "name": "millis",
              "type": "long",
              "doc": "The number of elapsed milliseconds, negative for a length back in time. Hours, minutes and seconds are carried here: an hour is 3600000 milliseconds, and 24 hours are not converted into a day."
            }
          ]
        }
      },
      "default": [],
      "doc": "When the user wants to be reminded, each as a duration added to start as spec/time.md, section 7.2, says: negative before start, such as -PT15M for 15 minutes before or -P1D for the day before at the same time on the wall clock, 0 at start, and positive after it. Empty when there are no reminders.",
      "axt.label": "Reminders",
      "axt.label_translations": {
        "de": "Erinnerungen"
      },
      "axt.help": "When to be reminded, each before or after the start.",
      "axt.help_translations": {
        "de": "Wann erinnert werden soll, jeweils vor oder nach dem Beginn."
      },
      "axt.emoji": "⏰"
    }
  ]
}

{
  "type": "record",
  "name": "Car",
  "namespace": "axt.example.v1",
  "doc": "A car the user owns or drives.",
  "axt.version": 1,
  "axt.title": "model",
  "axt.label": "Car",
  "axt.label_translations": {
    "de": "Auto"
  },
  "axt.help": "A car that is owned or driven.",
  "axt.help_translations": {
    "de": "Ein Auto, das man besitzt oder fährt."
  },
  "axt.emoji": "🚗",
  "fields": [
    {
      "name": "make",
      "type": "string",
      "default": "",
      "doc": "The manufacturer, such as Volkswagen. Empty when not known.",
      "axt.label": "Make",
      "axt.label_translations": {
        "de": "Marke"
      },
      "axt.help": "The manufacturer, such as Volkswagen.",
      "axt.help_translations": {
        "de": "Der Hersteller, etwa Volkswagen."
      },
      "axt.emoji": "🏭"
    },
    {
      "name": "model",
      "type": "string",
      "default": "",
      "doc": "The model, such as Golf. Empty when not known.",
      "axt.label": "Model",
      "axt.label_translations": {
        "de": "Modell"
      },
      "axt.help": "The model, such as Golf.",
      "axt.help_translations": {
        "de": "Das Modell, etwa Golf."
      },
      "axt.emoji": "🚙"
    },
    {
      "name": "year",
      "type": [
        "null",
        "int"
      ],
      "default": null,
      "doc": "The model year, such as 2019, from 1886 to 9999: the year the manufacturer gives the model, which need not be a year in which the car was built or sold, and so a number rather than a date. Null when not known.",
      "axt.label": "Model year",
      "axt.label_translations": {
        "de": "Modelljahr"
      },
      "axt.help": "The model year, such as 2019.",
      "axt.help_translations": {
        "de": "Das Modelljahr, etwa 2019."
      },
      "axt.emoji": "📅",
      "axt.min": 1886,
      "axt.max": 9999
    },
    {
      "name": "plate",
      "type": "string",
      "default": "",
      "doc": "The licence plate number as written on the plate. Empty when the car has none or it is not known.",
      "axt.label": "Licence plate",
      "axt.label_translations": {
        "de": "Kennzeichen"
      },
      "axt.help": "The number as written on the licence plate.",
      "axt.help_translations": {
        "de": "Das Kennzeichen, wie es auf dem Schild steht."
      },
      "axt.emoji": "🪪",
      "axt.preferred_length": 10
    },
    {
      "name": "vin",
      "type": "string",
      "default": "",
      "doc": "The vehicle identification number of ISO 3779: 17 characters, each a digit or an upper-case letter other than I, O and Q. Empty when not known.",
      "axt.label": "VIN",
      "axt.label_translations": {
        "de": "FIN"
      },
      "axt.help": "The vehicle identification number: 17 letters and digits.",
      "axt.help_translations": {
        "de": "Die Fahrzeug-Identifizierungsnummer: 17 Buchstaben und Ziffern."
      },
      "axt.emoji": "🆔",
      "axt.pattern": "[A-HJ-NPR-Z0-9]{17}",
      "axt.preferred_length": 17,
      "axt.example": "WVWZZZ1KZAW000000",
      "axt.advanced": true
    },
    {
      "name": "odometer",
      "type": [
        "null",
        "long"
      ],
      "default": null,
      "doc": "The distance on the odometer, in odometer_unit, 0 or more. Null when not known.",
      "axt.label": "Odometer",
      "axt.label_translations": {
        "de": "Tachostand"
      },
      "axt.help": "The distance on the odometer, in its unit.",
      "axt.help_translations": {
        "de": "Die Strecke auf dem Tacho, in dessen Einheit."
      },
      "axt.emoji": "🔢",
      "axt.min": 0
    },
    {
      "name": "odometer_unit",
      "type": {
        "type": "enum",
        "name": "CarDistanceUnit",
        "doc": "A unit of distance. KILOMETRE: kilometres. MILE: international miles. UNKNOWN: a unit this version does not name; a symbol this version does not know is read as UNKNOWN.",
        "symbols": [
          "KILOMETRE",
          "MILE",
          "UNKNOWN"
        ],
        "default": "UNKNOWN",
        "axt.symbols": {
          "KILOMETRE": {
            "label": "Kilometres",
            "label_translations": {
              "de": "Kilometer"
            },
            "emoji": "📏"
          },
          "MILE": {
            "label": "Miles",
            "label_translations": {
              "de": "Meilen"
            },
            "emoji": "🛣️"
          },
          "UNKNOWN": {
            "label": "Unknown",
            "label_translations": {
              "de": "Unbekannt"
            },
            "emoji": "❔"
          }
        }
      },
      "default": "KILOMETRE",
      "doc": "The unit of odometer.",
      "axt.label": "Odometer unit",
      "axt.label_translations": {
        "de": "Einheit des Tachos"
      },
      "axt.help": "Whether the odometer counts kilometres or miles.",
      "axt.help_translations": {
        "de": "Ob der Tacho Kilometer oder Meilen zählt."
      },
      "axt.emoji": "📐"
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the car, as plain text; lines are separated by LF. Empty when there are none.",
      "axt.label": "Notes",
      "axt.label_translations": {
        "de": "Notizen"
      },
      "axt.help": "Anything else about the car.",
      "axt.help_translations": {
        "de": "Alles Weitere zum Auto."
      },
      "axt.emoji": "📝",
      "axt.multiline": true
    }
  ]
}

{
  "type": "record",
  "name": "Document",
  "namespace": "axt.example.v1",
  "doc": "A document: a file with a title, such as a scanned invoice, a certificate or a photo.",
  "axt.version": 1,
  "axt.title": "title",
  "axt.label": "Document",
  "axt.label_translations": {
    "de": "Dokument"
  },
  "axt.help": "A file with a title, such as a scanned invoice, a certificate or a photo.",
  "axt.help_translations": {
    "de": "Eine Datei mit Titel, etwa eine eingescannte Rechnung, eine Bescheinigung oder ein Foto."
  },
  "axt.emoji": "📄",
  "fields": [
    {
      "name": "title",
      "type": "string",
      "default": "",
      "doc": "What the document is, as plain text on one line.",
      "axt.label": "Title",
      "axt.label_translations": {
        "de": "Titel"
      },
      "axt.help": "What the document is, on one line.",
      "axt.help_translations": {
        "de": "Was das Dokument ist, in einer Zeile."
      },
      "axt.emoji": "🏷️"
    },
    {
      "name": "file_name",
      "type": "string",
      "default": "",
      "doc": "The file's name with its extension, such as invoice-2026-11.pdf. Empty when not known.",
      "axt.label": "File name",
      "axt.label_translations": {
        "de": "Dateiname"
      },
      "axt.help": "The file's name with its extension, such as invoice-2026-11.pdf.",
      "axt.help_translations": {
        "de": "Der Name der Datei mit Endung, etwa invoice-2026-11.pdf."
      },
      "axt.emoji": "🗂️",
      "axt.advanced": true
    },
    {
      "name": "media_type",
      "type": "string",
      "default": "application/octet-stream",
      "doc": "The media type of content as in RFC 6838, such as application/pdf or image/jpeg, without parameters.",
      "axt.label": "File type",
      "axt.label_translations": {
        "de": "Dateityp"
      },
      "axt.help": "The media type of the file, such as application/pdf.",
      "axt.help_translations": {
        "de": "Der Medientyp der Datei, etwa application/pdf."
      },
      "axt.emoji": "🧾",
      "axt.format": "media-type",
      "axt.placeholder": "application/pdf",
      "axt.advanced": true
    },
    {
      "name": "content",
      "type": "bytes",
      "default": "",
      "doc": "The file's content. The whole message, this record included, must stay within the message limit of the AXT envelope.",
      "axt.label": "File",
      "axt.label_translations": {
        "de": "Datei"
      },
      "axt.help": "The file itself.",
      "axt.help_translations": {
        "de": "Die Datei selbst."
      },
      "axt.emoji": "📎"
    },
    {
      "name": "dated",
      "type": [
        "null",
        {
          "type": "record",
          "name": "Date",
          "namespace": "axt",
          "doc": "A calendar date of the proleptic Gregorian calendar, of which a part may be unknown, such as a birthday without a year (null, 5, 3), a year alone (2019, null, null) or a month of a year (2027, 3, null). At least one part is not null, and a day has its month. Defined in spec/time.md. Its schema never changes.",
          "fields": [
            {
              "name": "year",
              "type": [
                "null",
                "int"
              ],
              "default": null,
              "doc": "The year, 1 to 9999. Null when the year is not known or does not matter."
            },
            {
              "name": "month",
              "type": [
                "null",
                "int"
              ],
              "default": null,
              "doc": "The month of the year, 1 (January) to 12 (December). Null when the month is not known; then day is null as well."
            },
            {
              "name": "day",
              "type": [
                "null",
                "int"
              ],
              "default": null,
              "doc": "The day of the month, 1 to the number of days of the month: of that year when the year is known, otherwise of a leap year, so that 29 February is valid without a year. Null when the day is not known."
            }
          ]
        }
      ],
      "default": null,
      "doc": "The date the document bears, such as the date of an invoice, or only its month or year where it names no day. Null when it bears none.",
      "axt.label": "Date",
      "axt.label_translations": {
        "de": "Datum"
      },
      "axt.help": "The date the document bears, such as the date of an invoice.",
      "axt.help_translations": {
        "de": "Das Datum, das das Dokument trägt, etwa das Datum einer Rechnung."
      },
      "axt.emoji": "📅"
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the document, as plain text; lines are separated by LF. Empty when there are none.",
      "axt.label": "Notes",
      "axt.label_translations": {
        "de": "Notizen"
      },
      "axt.help": "Anything else about the document.",
      "axt.help_translations": {
        "de": "Alles Weitere zum Dokument."
      },
      "axt.emoji": "📝",
      "axt.multiline": true
    }
  ]
}

{
  "type": "record",
  "name": "Measurement",
  "namespace": "axt.example.v1",
  "doc": "One measured value or count at a point in time, such as a weight, a blood pressure reading or a tally of glasses of water.",
  "axt.version": 1,
  "axt.title": "quantity",
  "axt.label": "Measurement",
  "axt.label_translations": {
    "de": "Messung"
  },
  "axt.help": "A measured value or a count at a point in time, such as a weight.",
  "axt.help_translations": {
    "de": "Ein gemessener Wert oder eine Zählung zu einem Zeitpunkt, etwa ein Gewicht."
  },
  "axt.emoji": "📈",
  "fields": [
    {
      "name": "quantity",
      "type": "string",
      "default": "",
      "doc": "What was measured or counted, as the user calls it, such as Weight or Glasses of water.",
      "axt.label": "Quantity",
      "axt.label_translations": {
        "de": "Messgröße"
      },
      "axt.help": "What was measured or counted, such as Weight or Glasses of water.",
      "axt.help_translations": {
        "de": "Was gemessen oder gezählt wurde, etwa Gewicht oder Gläser Wasser."
      },
      "axt.emoji": "📋"
    },
    {
      "name": "value",
      "type": "double",
      "doc": "The measured value or the count, in unit.",
      "axt.label": "Value",
      "axt.label_translations": {
        "de": "Wert"
      },
      "axt.help": "The measured value or the count.",
      "axt.help_translations": {
        "de": "Der gemessene Wert oder die Anzahl."
      },
      "axt.emoji": "🔢"
    },
    {
      "name": "unit",
      "type": "string",
      "default": "1",
      "doc": "The unit of value as a case-sensitive code of UCUM, such as kg, Cel or mm[Hg]. A count is 1, or an annotation in braces alone that names what is counted, such as {glass}.",
      "axt.label": "Unit",
      "axt.label_translations": {
        "de": "Einheit"
      },
      "axt.help": "The unit as a code of UCUM, such as kg; 1 for a count.",
      "axt.help_translations": {
        "de": "Die Einheit als Code von UCUM, etwa kg; 1 für eine Anzahl."
      },
      "axt.emoji": "📐",
      "axt.format": "ucum",
      "axt.placeholder": "kg",
      "axt.example": "mm[Hg]",
      "axt.preferred_length": 10
    },
    {
      "name": "measured_at",
      "type": {
        "type": "record",
        "name": "DateTime",
        "namespace": "axt",
        "doc": "A date and time on the wall clock, to the millisecond, either in a time zone of the IANA time zone database, with the offset from UTC and the instant as the writer's zone rules gave them, or floating, on the wall clock of wherever the user is, without zone, offset and instant. Defined in spec/time.md. Its schema never changes.",
        "fields": [
          {
            "name": "year",
            "type": "int",
            "doc": "The year of the proleptic Gregorian calendar, 1 to 9999."
          },
          {
            "name": "month",
            "type": "int",
            "doc": "The month, 1 (January) to 12 (December)."
          },
          {
            "name": "day",
            "type": "int",
            "doc": "The day of the month, 1 to the number of days of that month in that year."
          },
          {
            "name": "hour",
            "type": "int",
            "doc": "The hour on the wall clock, 0 to 23."
          },
          {
            "name": "minute",
            "type": "int",
            "doc": "The minute, 0 to 59."
          },
          {
            "name": "second",
            "type": "int",
            "doc": "The second, 0 to 59; a leap second is not written as 60."
          },
          {
            "name": "millisecond",
            "type": "int",
            "doc": "The millisecond, 0 to 999."
          },
          {
            "name": "zone",
            "type": [
              "null",
              "string"
            ],
            "default": null,
            "doc": "The name of the time zone in the IANA time zone database, such as Europe/Berlin. Null for a floating time; then offset_seconds and instant_ms are null as well."
          },
          {
            "name": "offset_seconds",
            "type": [
              "null",
              "int"
            ],
            "default": null,
            "doc": "The offset of the wall clock from UTC, in seconds, -64800 to 64800, as the writer's rules of the zone gave it at the instant, such as 3600 for 01:00 east of UTC. Null for a floating time, and only then."
          },
          {
            "name": "instant_ms",
            "type": [
              "null",
              "long"
            ],
